package run.ikaros.document; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/documents/{documentId}/embeds") public class DocumentEmbedController{private final DocumentEmbedService service;public DocumentEmbedController(DocumentEmbedService s){service=s;}@PostMapping public Mono<DocumentEmbedView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID documentId,@Valid@RequestBody CreateDocumentEmbedRequest r){return service.create(o,documentId,r);}@GetMapping public Flux<DocumentEmbedView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID documentId){return service.list(o,documentId);}@DeleteMapping("/{embedId}")public Mono<Void> delete(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID embedId){return service.delete(o,embedId);}}
